export type experimentAnnotationsLogicType = MakeLogicType<
    experimentAnnotationsLogicValues,
    experimentAnnotationsLogicActions,
    ExperimentAnnotationsLogicProps,
    experimentAnnotationsLogicMeta
>

export const experimentAnnotationsLogic: LogicWrapper<experimentAnnotationsLogicType> =
    kea<experimentAnnotationsLogicType>([
        props({} as ExperimentAnnotationsLogicProps),
        key(({ projectId, experimentId }) => `${projectId}-${experimentId}`),
        path((key) => ['products', 'experiments', 'frontend', 'annotations', 'experimentAnnotationsLogic', key]),
        actions({
            setVariantKey: (variantKey: string) => ({ variantKey }),
            setContent: (content: string) => ({ content }),
            editAnnotation: (annotation: ExperimentAnnotationApi) => ({ annotation }),
            cancelEditing: true,
        }),
        loaders(({ props, values }) => ({
            annotations: [
                null as ExperimentAnnotationApi[] | null,
                {
                    loadExperimentAnnotations: async () =>
                        await api.experimentsAnnotationsList(props.projectId, props.experimentId),
                },
            ],
            annotationMutation: [
                null as boolean | null,
                {
                    saveExperimentAnnotation: async () => {
                        if (values.editingId !== null) {
                            await api.experimentsAnnotationsPartialUpdate(
                                props.projectId,
                                props.experimentId,
                                values.editingId,
                                { content: values.content.trim() }
                            )
                        } else {
                            await api.experimentsAnnotationsCreate(props.projectId, props.experimentId, {
                                variant_key: values.variantKey,
                                content: values.content.trim(),
                            })
                        }
                        return true
                    },
                    deleteExperimentAnnotation: async ({ id }: { id: number }) => {
                        await api.experimentsAnnotationsDestroy(props.projectId, props.experimentId, id)
                        return true
                    },
                },
            ],
        })),
        reducers({
            variantKey: [
                '',
                {
                    setVariantKey: (_, { variantKey }) => variantKey,
                    editAnnotation: (_, { annotation }) => annotation.variant_key,
                    cancelEditing: () => '',
                },
            ],
            content: [
                '',
                {
                    setContent: (_, { content }) => content,
                    editAnnotation: (_, { annotation }) => annotation.content,
                    cancelEditing: () => '',
                },
            ],
            editingId: [
                null as number | null,
                {
                    editAnnotation: (_, { annotation }) => annotation.id,
                    cancelEditing: () => null,
                },
            ],
            annotationError: [
                null as string | null,
                {
                    loadExperimentAnnotations: () => null,
                    saveExperimentAnnotation: () => null,
                    deleteExperimentAnnotation: () => null,
                    loadExperimentAnnotationsFailure: () => "Couldn't load annotations. Try again.",
                    saveExperimentAnnotationFailure: () => "Couldn't save your annotation. Try again.",
                },
            ],
            annotationLoadError: [
                false,
                {
                    loadExperimentAnnotations: () => false,
                    loadExperimentAnnotationsFailure: () => true,
                },
            ],
        }),
        listeners(({ actions, values }) => ({
            saveExperimentAnnotationSuccess: () => {
                actions.cancelEditing()
                actions.loadExperimentAnnotations()
            },
            deleteExperimentAnnotationSuccess: ({ payload }) => {
                if (payload?.id === values.editingId) {
                    actions.cancelEditing()
                }
                actions.loadExperimentAnnotations()
            },
        })),
        afterMount(({ actions }) => actions.loadExperimentAnnotations()),
    ])
